using Azure.Storage.Blobs; using Azure.Storage.Blobs.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.Services; namespace RaceDay.Api.Controllers; [ApiController,Authorize,Route("api/files")] public class FilesController(RaceDayDbContext db,IConfiguration cfg):ControllerBase { const long Limit=5*1024*1024; static readonly string[] Exts={".jpg",".jpeg",".png",".webp"}; async Task<(BlobContainerClient? Client,string? Error)> Container(){var cs=cfg["AzureBlobStorage:ConnectionString"];if(string.IsNullOrWhiteSpace(cs))return(null,"Azure Blob Storage is not configured on the API.");try{var c=new BlobServiceClient(cs).GetBlobContainerClient(cfg["AzureBlobStorage:ContainerName"]??"raceday-images");await c.CreateIfNotExistsAsync(PublicAccessType.Blob);return(c,null);}catch{return(null,"Azure Blob Storage is unavailable. Check API configuration.");}} string? Check(IFormFile? f)=>f==null||f.Length==0?"Choose an image file.":f.Length>Limit?"Image must be 5 MB or smaller.":!Exts.Contains(Path.GetExtension(f.FileName).ToLowerInvariant())||!f.ContentType.StartsWith("image/",StringComparison.OrdinalIgnoreCase)?"Only JPG, PNG and WebP images are accepted.":null; [HttpPost("event-banner"),Authorize(Roles="Organiser")] public async Task<IActionResult> Banner(int eventId,IFormFile file){var err=Check(file);if(err!=null)return BadRequest(new{message=err});var e=await db.Events.SingleOrDefaultAsync(x=>x.EventId==eventId);if(e==null)return NotFound();if(e.OrganiserId!=User.UserId())return Forbid();var(c,msg)=await Container();if(c==null)return StatusCode(503,new{message=msg});var blob=c.GetBlobClient($"event-banners/{eventId}/{Guid.NewGuid():N}{Path.GetExtension(file.FileName).ToLowerInvariant()}");await using var s=file.OpenReadStream();await blob.UploadAsync(s,new BlobHttpHeaders{ContentType=file.ContentType});e.BannerImageUrl=blob.Uri.ToString();await db.SaveChangesAsync();return Ok(new{url=e.BannerImageUrl});} [HttpPost("profile-picture"),Authorize(Roles="Participant")] public async Task<IActionResult> Picture(IFormFile file){var err=Check(file);if(err!=null)return BadRequest(new{message=err});var u=await db.Users.FindAsync(User.UserId());if(u==null)return NotFound();var(c,msg)=await Container();if(c==null)return StatusCode(503,new{message=msg});var blob=c.GetBlobClient($"profile-pictures/{u.UserId}/{Guid.NewGuid():N}{Path.GetExtension(file.FileName).ToLowerInvariant()}");await using var s=file.OpenReadStream();await blob.UploadAsync(s,new BlobHttpHeaders{ContentType=file.ContentType});u.ProfilePictureUrl=blob.Uri.ToString();await db.SaveChangesAsync();return Ok(new{url=u.ProfilePictureUrl});} }